import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import { CreditCard, Smartphone, Building2, ToggleLeft, ToggleRight, Shield } from 'lucide-react';
import toast from 'react-hot-toast';
import adminService from '../../services/adminService.js';
import paymentService from '../../services/paymentService';
import DataTable from '../../components/datadisplay/DataTable';
import StatusBadge from '../../components/datadisplay/StatusBadge';

const PaymentSettings = () => {
    const queryClient = useQueryClient();
    const [toggling, setToggling] = useState(null);

    const { data: config, isLoading: configLoading } = useQuery({
        queryKey: ['payment-config'],
        queryFn: paymentService.getPaymentConfig
    });

    const { data: transactions, isLoading: txLoading } = useQuery({
        queryKey: ['payment-transactions'],
        queryFn: () => paymentService.getTransactionHistory()
    });

    const toggleMutation = useMutation({
        mutationFn: ({ method, enabled }) => paymentService.togglePaymentMethod(method, enabled),
        onSuccess: () => {
            toast.success('Payment method updated');
            queryClient.invalidateQueries(['payment-config']);
            setToggling(null);
        },
        onError: (error) => {
            toast.error('Failed to update payment method');
            setToggling(null);
        }
    });

    const handleToggle = (method, currentState) => {
        setToggling(method);
        toggleMutation.mutate({ method, enabled: !currentState });
    };

    const columns = [
        {
            key: 'reference',
            label: 'Reference',
            render: (row) => (
                <span className="font-mono text-sm">{row.reference}</span>
            )
        },
        {
            key: 'provider',
            label: 'Provider',
            render: (row) => (
                <span className="capitalize font-medium">{row.provider}</span>
            )
        },
        {
            key: 'amount',
            label: 'Amount',
            render: (row) => (
                <span className="font-medium">${parseFloat(row.amount).toFixed(2)}</span>
            )
        },
        {
            key: 'status',
            label: 'Status',
            render: (row) => (
                <StatusBadge status={row.status} size="sm" />
            )
        },
        {
            key: 'created_at',
            label: 'Date',
            render: (row) => (
                <span className="text-sm text-gray-500">
                    {new Date(row.created_at).toLocaleDateString()}
                </span>
            )
        }
    ];

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Payment Settings</h1>
                <p className="text-gray-500 dark:text-gray-400 mt-1">
                    Manage payment methods and view transactions
                </p>
            </div>

            {/* Payment Methods Toggle */}
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6"
            >
                <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-6">
                    Payment Methods
                </h3>

                <div className="space-y-4">
                    {/* Online Payment */}
                    <div className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-900 rounded-lg">
                        <div className="flex items-center gap-3">
                            <div className="p-2 bg-indigo-100 dark:bg-indigo-900/30 rounded-lg">
                                <CreditCard className="h-6 w-6 text-indigo-600" />
                            </div>
                            <div>
                                <p className="font-medium text-gray-900 dark:text-white">Online Payment</p>
                                <p className="text-sm text-gray-500">Paystack & Flutterwave</p>
                            </div>
                        </div>
                        <button
                            onClick={() => handleToggle('online', config?.onlineEnabled)}
                            disabled={toggling === 'online' && toggleMutation.isLoading}
                            className="relative"
                        >
                            {config?.onlineEnabled ? (
                                <ToggleRight className="h-8 w-14 text-emerald-500" />
                            ) : (
                                <ToggleLeft className="h-8 w-14 text-gray-400" />
                            )}
                        </button>
                    </div>

                    {/* Pay on Delivery */}
                    <div className="flex items-center justify-between p-4 bg-gray-50 dark:bg-gray-900 rounded-lg">
                        <div className="flex items-center gap-3">
                            <div className="p-2 bg-teal-100 dark:bg-teal-900/30 rounded-lg">
                                <Smartphone className="h-6 w-6 text-teal-600" />
                            </div>
                            <div>
                                <p className="font-medium text-gray-900 dark:text-white">Pay on Delivery</p>
                                <p className="text-sm text-gray-500">Cash or card on delivery</p>
                            </div>
                        </div>
                        <button
                            onClick={() => handleToggle('delivery', config?.deliveryEnabled)}
                            disabled={toggling === 'delivery' && toggleMutation.isLoading}
                        >
                            {config?.deliveryEnabled ? (
                                <ToggleRight className="h-8 w-14 text-emerald-500" />
                            ) : (
                                <ToggleLeft className="h-8 w-14 text-gray-400" />
                            )}
                        </button>
                    </div>
                </div>
            </motion.div>

            {/* API Keys Section */}
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.1 }}
                className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6"
            >
                <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
                    <Shield className="h-5 w-5 text-indigo-600" />
                    Payment Gateway Configuration
                </h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="p-4 bg-gray-50 dark:bg-gray-900 rounded-lg">
                        <div className="flex items-center gap-2 mb-3">
                            <Building2 className="h-5 w-5 text-indigo-600" />
                            <span className="font-medium text-gray-900 dark:text-white">Paystack</span>
                        </div>
                        <div className="space-y-2 text-sm text-gray-500">
                            <p>Status: <span className="text-emerald-600 font-medium">Configured</span></p>
                            <p>Public Key: ••••••••{process.env.REACT_APP_PAYSTACK_KEY?.slice(-4)}</p>
                            <p>Webhook URL: /api/payments/webhook/paystack</p>
                        </div>
                    </div>

                    <div className="p-4 bg-gray-50 dark:bg-gray-900 rounded-lg">
                        <div className="flex items-center gap-2 mb-3">
                            <Building2 className="h-5 w-5 text-teal-600" />
                            <span className="font-medium text-gray-900 dark:text-white">Flutterwave</span>
                        </div>
                        <div className="space-y-2 text-sm text-gray-500">
                            <p>Status: <span className="text-emerald-600 font-medium">Configured</span></p>
                            <p>Public Key: ••••••••{process.env.REACT_APP_FLUTTERWAVE_KEY?.slice(-4)}</p>
                            <p>Webhook URL: /api/payments/webhook/flutterwave</p>
                        </div>
                    </div>
                </div>
            </motion.div>

            {/* Transaction History */}
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 }}
            >
                <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
                    Transaction History
                </h3>
                <DataTable
                    columns={columns}
                    data={transactions?.data || []}
                    pagination={transactions?.pagination}
                    loading={txLoading}
                    emptyMessage="No transactions found"
                />
            </motion.div>
        </div>
    );
};

export default PaymentSettings;
